import React from 'react';
import './App.css';

/** The sheet's columns, A to N, and its ten rows. */
export const COLUMNS = 'ABCDEFGHIJKLMN'.split('');
export const ROW_COUNT = 10;

/** A cell by its 0-based column and row. */
export interface Cell {
  col: number;
  row: number;
}

/** "B2": the name a cell shows and carries in `data-cell`. */
export function cellName(cell: Cell): string {
  return `${COLUMNS[cell.col]}${cell.row + 1}`;
}

export default function App() {
  // TODO: select cells with the mouse: a press and a release on one cell select it, a drag selects the rectangle
  // between the cell pressed and the cell under the pointer, and Shift with a click extends from where it started.
  // TODO: with focus on a cell, move the active cell with the arrow keys, extend with Shift, and clear with Escape.
  // TODO: mark selected cells with `aria-selected="true"` and keep `.selection-summary` in step with them.
  return (
    <main className="sheet-page">
      <p className="selection-summary" role="status">No cells selected</p>
      <div className="sheet" role="grid" aria-label="Seats" aria-multiselectable="true">
        {Array.from({ length: ROW_COUNT }, (_, row) => (
          <div className="sheet-row" role="row" key={row}>
            {COLUMNS.map((_, col) => {
              const name = cellName({ col, row });
              return (
                <div key={name} className="cell" role="gridcell" data-cell={name} aria-selected={false} tabIndex={-1}>
                  {name}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </main>
  );
}

