* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: #111827;
  background: #f9fafb;
}

.sheet-page {
  display: grid;
  gap: 12px;
  max-width: 600px;
  margin: 0 auto;
  padding: 16px;
}

.selection-summary {
  margin: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.sheet {
  display: grid;
  gap: 2px;
  max-width: 100%;
  overflow-x: auto;
  user-select: none;
}

.sheet-row {
  display: grid;
  grid-template-columns: repeat(14, 36px);
  gap: 2px;
}

.cell {
  display: grid;
  place-items: center;
  height: 32px;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  font-size: 12px;
  background: #ffffff;
  cursor: pointer;
}

.cell[aria-selected='true'] {
  border-color: #2563eb;
  background: #dbeafe;
}

.cell:focus-visible {
  outline: 2px solid #1d4ed8;
  outline-offset: 1px;
}
